# App database role — REFERENCE ONLY
#
# The executable version is `docker/postgres/01-app-role.sh`, which is
# mounted as a single flat file into Postgres' init directory and runs
# once on first init of an empty data directory. Do not edit this file
# expecting it to take effect; edit the .sh file instead. This file
# exists so the SQL is reviewable without reading shell.
#
# Role: fixflow_app — LOGIN, NOBYPASSRLS. Never a superuser, never an
# owner, never runs migrations. Migrations run as fixflow_owner via
# `prisma migrate deploy` in apps/api/scripts/migrate-and-start.sh.
#
#   CREATE ROLE fixflow_app WITH LOGIN NOBYPASSRLS PASSWORD '<from APP_DB_PASSWORD>';
#   REVOKE ALL ON SCHEMA public FROM fixflow_app;
#   GRANT USAGE ON SCHEMA public TO fixflow_app;
#   ALTER DEFAULT PRIVILEGES FOR ROLE fixflow_owner IN SCHEMA public
#     GRANT SELECT, INSERT, UPDATE, DELETE ON TABLES TO fixflow_app;
#   ALTER DEFAULT PRIVILEGES FOR ROLE fixflow_owner IN SCHEMA public
#     GRANT USAGE, SELECT ON SEQUENCES TO fixflow_app;
#
# RLS note: a missing policy on an RLS-enabled table is default-deny,
# not a leak. Disabled RLS or a BYPASSRLS / owner role can leak — that
# is why the app role is NOBYPASSRLS and the app never connects as the
# owner. Verify with:
#   SELECT rolname, rolbypassrls, rolsuper FROM pg_roles WHERE rolname IN ('fixflow_app','fixflow_owner');
# Expected: fixflow_app has rolbypassrls = f and rolsuper = f.
